-- TPC-H "tables" for ClickHouse over Parquet files. Nothing is loaded: each view reads the
-- file generated by `tpchgen parquet` in <user_files>/tpch/ (mounted into the container).
-- Column types come from the Parquet schema (Decimal(15,2), Date32, Int64 keys).
CREATE VIEW nation   AS SELECT * FROM file('tpch/nation.parquet',   Parquet);
CREATE VIEW region   AS SELECT * FROM file('tpch/region.parquet',   Parquet);
CREATE VIEW part     AS SELECT * FROM file('tpch/part.parquet',     Parquet);
CREATE VIEW supplier AS SELECT * FROM file('tpch/supplier.parquet', Parquet);
CREATE VIEW partsupp AS SELECT * FROM file('tpch/partsupp.parquet', Parquet);
CREATE VIEW customer AS SELECT * FROM file('tpch/customer.parquet', Parquet);
CREATE VIEW orders   AS SELECT * FROM file('tpch/orders.parquet',   Parquet);
CREATE VIEW lineitem AS SELECT * FROM file('tpch/lineitem.parquet', Parquet);
